head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[inputCalendar > M > setCalendarValueType]<br/>컴포넌트의 calendarValueType 속성을 설정합니다.",
    "validation" : [
        "calendarValueType(필수) 파라미터로 컴포넌트에 입력할 수 있는 날짜 및 시간의 종류를 설정합니다.",
        "calendarValueType(필수) 파라미터로 yearMonthDate 설정 시 컴포넌트에 '년/월/일' 을 입력할 수 있습니다.",
        "calendarValueType(필수) 파라미터로 yearMonthDate 설정 시 options 파라미터 생략하면 displayFormat, ioFormat 속성에 각각 'yyyy{d}MM{d}dd', 'yyyyMMdd' 가 설정됩니다.",
        "calendarValueType(필수) 파라미터로 year 설정 시 컴포넌트에 '연도' 를 입력할 수 있습니다.",
        "calendarValueType(필수) 파라미터로 year 설정 시 options 파라미터 생략하면 displayFormat, ioFormat 속성에 각각 'yyyy', 'yyyy' 가 설정됩니다.",
        "calendarValueType(필수) 파라미터로 yearMonth 설정 시 컴포넌트에 '년/월' 을 입력할 수 있습니다.",
        "calendarValueType(필수) 파라미터로 yearMonth 설정 시 options 파라미터 생략하면 displayFormat, ioFormat 속성에 각각 'yyyy{d}MM', 'yyyyMM' 가 설정됩니다.",
        "calendarValueType(필수) 파라미터로 yearMonthDateHour 설정 시 컴포넌트에 '년/월/일/시' 를 입력할 수 있습니다.",
        "calendarValueType(필수) 파라미터로 yearMonthDateHour 설정 시 options 파라미터 생략하면 displayFormat, ioFormat 속성에 각각 'yyyy{d}MM{d}dd HH', 'yyyyMMddHH' 가 설정됩니다.",
        "calendarValueType(필수) 파라미터로 yearMonthDateTime 설정 시 컴포넌트에 '년/월/일/시/분' 을 입력할 수 있습니다.",
        "calendarValueType(필수) 파라미터로 yearMonthDateTime 설정 시 options 파라미터 생략하면 displayFormat, ioFormat 속성에 각각 'yyyy{d}MM{d}dd HH:mm', 'yyyyMMddHHmm' 가 설정됩니다.",
        "calendarValueType(필수) 파라미터로 yearMonthDateTimeSec 설정 시 컴포넌트에 '년/월/일/시/분/초' 를 입력할 수 있습니다.",
        "calendarValueType(필수) 파라미터로 yearMonthDateTime 설정 시 options 파라미터 생략하면 displayFormat, ioFormat 속성에 각각 'yyyy{d}MM{d}dd HH:mm:SS', 'yyyyMMddHHmmSS' 가 설정됩니다.",
        "options(선택) 파라미터로 calendarValueType 속성값과 함께 설정할 ioFormat, displayFormat 속성값을 객체로 설정합니다.",
        "options.ioFormat(선택) 파라미터로 새로 설정할 ioFormat 속성값을 설정합니다.",
        "options.ioFormat(선택) 파라미터 값을 설정하지 않으면 속성값에 맞는 기본값이 설정됩니다.",
        "options.displayFormat(선택) 파라미터로 새로 설정할 displayFormat 속성값을 설정합니다.",
        "options.displayFormat(선택) 파라미터 값을 설정하지 않으면 속성값에 맞는 기본값이 설정됩니다.",
        "displayFormat 속성이 기본값으로 적용될때 '{d}' 엔 delimiter 속성값이 적용됩니다.",
        "calendarValueType 속성값에 따라 컴포넌트의 class 속성에 'w2inputCalenar_type_{속성값}' 의 클래스가 설정됩니다.",
    ]
}



scwin.onpageload = function () {
    $c.gcm.createCommonDatalist();

    wf_body_left.getObj("scwin").createValidation(scwin.tData);

    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    let properties = {                
        delimiter : "/",
        style : 'width:300px',
    }

    let cList = $c.gcm.createCList(properties)

    // comp 생성 함수 호출
    $c.gcm.createEmptyInputCalendar(cList);
}



scwin.btn_getCalendarValueType_onclick = function (e) {
    target1.setValue("20251111111111");

    let rtn = '';

    rtn = target1.getDisplayFormat();
	wf_body_bottom.getObj("scwin").setReturnValue('displayFormat : ' + rtn);   

    rtn = target1.getIoFormat();
	wf_body_bottom.getObj("scwin").setReturnValue('ioFormat : ' + rtn);   

    rtn = target1.getDisplayValue();
	wf_body_bottom.getObj("scwin").setReturnValue('getDisplayValue : ' + rtn);   

    rtn = target1.render.className;
    wf_body_bottom.getObj("scwin").setReturnValue('className : ' + rtn);  
};



scwin.btn_setCalendarValueType_onclick = function (e) {
    let calendarValueType = par_calendarValueType.getText();
    let ioFormat = par_ioFormat.getText();
    let displayFormat = par_displayFormat.getText();   

    if (ioFormat == '' && displayFormat == '')
        target1.setCalendarValueType(calendarValueType);
    else if (ioFormat != '' && displayFormat == '')
        target1.setCalendarValueType(calendarValueType, {"ioFormat" : ioFormat});
    else 
    	target1.setCalendarValueType(calendarValueType, {"ioFormat" : ioFormat, "displayFormat" : displayFormat});

    scwin.btn_getCalendarValueType_onclick();
};



scwin.par_calendarValueType_onchange = function (info) {
    let calendarValueType = par_calendarValueType.getValue();

    par_ioFormat.setValue(calendarValueType);	
    par_displayFormat.setValue(calendarValueType);    
};
